record If(String name, String ip, String status, String protocol) { boolean problem() { return !(status.equals("up") && protocol.equals("up")) && !status.startsWith("administratively"); } }
static List<If> parse(String out) {
  return out.lines().skip(1).filter(l -> !l.isBlank()).map(l -> {
    String[] p = l.trim().split("\\s+");
    String proto = p[p.length - 1];
    String status = p[p.length - 2].equals("down") && p[p.length - 3].equals("administratively") ? "administratively down" : p[p.length - 2];
    return new If(p[0], p[1], status, proto);
  }).toList();
}
